create or replace function public.clock_in_staff(p_lat numeric default null,p_lng numeric default null,p_accuracy_meters numeric default null,p_device text default null,p_network_state text default 'online',p_client_event_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_staff public.staff%rowtype; v_policy public.attendance_policies%rowtype; v_location public.business_locations%rowtype; v_record public.attendance_records%rowtype; v_local_date date; v_now timestamptz:=now(); v_distance numeric; v_status text:='present'; v_verification text:='unverified'; v_reason text:='No business location configured'; v_event_id uuid; begin select * into v_staff from public.staff where user_id=(select auth.uid()) limit 1; if v_staff.id is null then raise exception using errcode='42501',message='STAFF_NOT_FOUND'; end if; select * into v_policy from public.attendance_policies where business_id=v_staff.business_id; v_local_date:=(v_now at time zone coalesce(v_policy.timezone,'Africa/Lagos'))::date; select * into v_record from public.attendance_records where staff_id=v_staff.id and date=v_local_date for update; if v_record.id is not null and v_record.check_in_at is not null then return jsonb_build_object('ok',true,'duplicate',true,'attendance_id',v_record.id,'status',v_record.status,'verification_status',v_record.verification_status); end if; select * into v_location from public.business_locations where business_id=v_staff.business_id and is_active=true and is_primary=true limit 1; if p_lat is not null and p_lng is not null and v_location.id is not null then v_distance:=extensions.st_distance(v_location.location,extensions.st_setsrid(extensions.st_makepoint(p_lng::double precision,p_lat::double precision),4326)::extensions.geography); if v_distance<=coalesce(v_location.radius_meters,v_policy.default_radius_meters,150) then v_verification:='verified';v_reason:='Within expected business location'; else v_verification:='outside_geofence';v_reason:='Outside expected business location radius'; if coalesce(v_policy.block_outside_geofence,false) then raise exception using errcode='P0001',message='OUTSIDE_GEOFENCE'; end if; end if; elsif coalesce(v_policy.require_location,false) then raise exception using errcode='P0001',message='LOCATION_REQUIRED'; end if; if (v_now at time zone coalesce(v_policy.timezone,'Africa/Lagos'))::time>(coalesce(v_policy.work_start,'09:00'::time)+make_interval(mins=>coalesce(v_policy.grace_minutes,15))) then v_status:='late'; end if; if v_record.id is null then insert into public.attendance_records(staff_id,business_id,date,check_in_at,check_in,status,check_in_lat,check_in_lng,check_in_accuracy_meters,check_in_distance_meters,verification_status,verification_reason,evidence,client_event_id,server_received_at) values(v_staff.id,v_staff.business_id,v_local_date,v_now,v_now::time,v_status,p_lat,p_lng,p_accuracy_meters,v_distance,v_verification,v_reason,jsonb_build_object('captured_at',v_now,'source','staff_clock_in'),p_client_event_id,v_now) returning * into v_record; else update public.attendance_records set check_in_at=v_now,check_in=v_now::time,status=v_status,check_in_lat=p_lat,check_in_lng=p_lng,check_in_accuracy_meters=p_accuracy_meters,check_in_distance_meters=v_distance,verification_status=v_verification,verification_reason=v_reason,client_event_id=p_client_event_id,server_received_at=v_now,evidence=jsonb_build_object('captured_at',v_now,'source','staff_clock_in') where id=v_record.id returning * into v_record; end if; insert into public.attendance_events(business_id,staff_id,attendance_record_id,event_type,client_event_id,captured_at,server_received_at,latitude,longitude,accuracy_meters,distance_meters,verification_status,verification_reason,device,network_state,evidence) values(v_staff.business_id,v_staff.id,v_record.id,'clock_in',p_client_event_id,v_now,v_now,p_lat,p_lng,p_accuracy_meters,v_distance,v_verification,v_reason,p_device,p_network_state,jsonb_build_object('attendance_status',v_status)) on conflict(client_event_id) do nothing returning id into v_event_id; return jsonb_build_object('ok',true,'duplicate',false,'attendance_id',v_record.id,'event_id',coalesce(v_event_id,p_client_event_id),'status',v_status,'verification_status',v_verification,'verification_reason',v_reason,'distance_meters',v_distance); end; $$;

create or replace function public.clock_out_staff(p_lat numeric default null,p_lng numeric default null,p_accuracy_meters numeric default null,p_device text default null,p_network_state text default 'online',p_client_event_id uuid default gen_random_uuid()) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_staff public.staff%rowtype; v_policy public.attendance_policies%rowtype; v_location public.business_locations%rowtype; v_record public.attendance_records%rowtype; v_now timestamptz:=now(); v_distance numeric; v_verification text:='unverified'; v_reason text:='No business location configured'; v_event_id uuid; v_hours numeric; v_local_date date; begin select * into v_staff from public.staff where user_id=(select auth.uid()) limit 1; if v_staff.id is null then raise exception using errcode='42501',message='STAFF_NOT_FOUND'; end if; select * into v_policy from public.attendance_policies where business_id=v_staff.business_id; v_local_date:=(v_now at time zone coalesce(v_policy.timezone,'Africa/Lagos'))::date; select * into v_record from public.attendance_records where staff_id=v_staff.id and date=v_local_date for update; if v_record.id is null or v_record.check_in_at is null then raise exception using errcode='P0001',message='NOT_CLOCKED_IN'; end if; if v_record.check_out_at is not null then return jsonb_build_object('ok',true,'duplicate',true,'attendance_id',v_record.id,'status',v_record.status,'work_hours',v_record.work_hours); end if; select * into v_location from public.business_locations where business_id=v_staff.business_id and is_active=true and is_primary=true limit 1; if p_lat is not null and p_lng is not null and v_location.id is not null then v_distance:=extensions.st_distance(v_location.location,extensions.st_setsrid(extensions.st_makepoint(p_lng::double precision,p_lat::double precision),4326)::extensions.geography); if v_distance<=coalesce(v_location.radius_meters,v_policy.default_radius_meters,150) then v_verification:='verified';v_reason:='Within expected business location'; else v_verification:='outside_geofence';v_reason:='Outside expected business location radius'; end if; elsif coalesce(v_policy.require_location,false) then raise exception using errcode='P0001',message='LOCATION_REQUIRED'; end if; v_hours:=greatest(0,extract(epoch from(v_now-v_record.check_in_at))/3600.0); update public.attendance_records set check_out_at=v_now,check_out=v_now::time,work_hours=round(v_hours::numeric,2),check_out_lat=p_lat,check_out_lng=p_lng,check_out_accuracy_meters=p_accuracy_meters,check_out_distance_meters=v_distance,verification_status=case when verification_status='verified' and v_verification='verified' then 'verified' else coalesce(v_verification,verification_status) end,verification_reason=v_reason,server_received_at=v_now where id=v_record.id returning * into v_record; insert into public.attendance_events(business_id,staff_id,attendance_record_id,event_type,client_event_id,captured_at,server_received_at,latitude,longitude,accuracy_meters,distance_meters,verification_status,verification_reason,device,network_state,evidence) values(v_staff.business_id,v_staff.id,v_record.id,'clock_out',p_client_event_id,v_now,v_now,p_lat,p_lng,p_accuracy_meters,v_distance,v_verification,v_reason,p_device,p_network_state,jsonb_build_object('work_hours',v_record.work_hours)) on conflict(client_event_id) do nothing returning id into v_event_id; return jsonb_build_object('ok',true,'duplicate',false,'attendance_id',v_record.id,'event_id',coalesce(v_event_id,p_client_event_id),'work_hours',v_record.work_hours,'verification_status',v_record.verification_status,'verification_reason',v_record.verification_reason); end; $$;

revoke all on function public.clock_in_staff(numeric,numeric,numeric,text,text,uuid) from public,anon;
revoke all on function public.clock_out_staff(numeric,numeric,numeric,text,text,uuid) from public,anon;
grant execute on function public.clock_in_staff(numeric,numeric,numeric,text,text,uuid) to authenticated;
grant execute on function public.clock_out_staff(numeric,numeric,numeric,text,text,uuid) to authenticated;

notify pgrst,'reload schema';